alter table supplier_invoice add column if not exists purchase_receipt_document_id bigint references purchase_document(document_id);
create unique index if not exists supplier_invoice_one_per_purchase_receipt_idx on supplier_invoice(purchase_receipt_document_id) where purchase_receipt_document_id is not null;
create or replace function link_supplier_invoice_to_purchase_receipt()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$declare receipt_number text;begin if new.purchase_receipt_document_id is null then receipt_number:=substring(coalesce(new.memo,'')from'(REC_INV-[A-Za-z0-9_-]+)');if receipt_number is not null then select document_id into new.purchase_receipt_document_id from purchase_document where document_number=receipt_number and document_type='RECEIPT'and subsidiary_id=new.subsidiary_id;end if;end if;if new.purchase_receipt_document_id is not null and not exists(select 1 from purchase_document where document_id=new.purchase_receipt_document_id and document_type='RECEIPT'and subsidiary_id=new.subsidiary_id and supplier_id=new.supplier_id)then raise exception'La recepción relacionada no corresponde a la subsidiaria y proveedor de la factura.';end if;return new;end$$;
drop trigger if exists link_supplier_invoice_to_purchase_receipt_trigger on supplier_invoice;
create trigger link_supplier_invoice_to_purchase_receipt_trigger before insert or update on supplier_invoice for each row execute function link_supplier_invoice_to_purchase_receipt();
